// A person flagged a mistake in an agent run. Only the 8 problem agents have editable prompts.
const AGENTS = ['vehicle', 'journey', 'destination', 'tracking', 'incident', 'documents', 'expenses', 'general'];
const b = $json.body || {};
const order_ref = String(b.order_ref || '').trim().toUpperCase(), agent = String(b.agent || ''), complaint = String(b.complaint || '').trim();
if (!/^CD-\d+$/.test(order_ref)) throw new Error('order_ref like CD-420322 is required');
if (!AGENTS.includes(agent)) throw new Error('agent must be one of ' + AGENTS.join(', '));
if (complaint.length < 10) throw new Error('say what the agent got wrong (at least a short sentence)');
return [{ json: { order_ref, agent, complaint: complaint.slice(0, 1500), operator: String(b.operator || 'ops').slice(0, 60) } }];

// What the fixer sees: the complaint, what the agent did on this order (latest timeline lines) and its whole current prompt.
const f = $('Check').first().json, cur = $('Current prompt').first().json;
const lines = $('Run lines').all().map((x) => x.json).filter((r) => r.id).sort((a, b) => b.id - a.id).slice(0, 30).reverse()
  .map((r) => `[${r.actor} / ${r.kind}] ${String(r.text || '').slice(0, 600)}`).join('\n');
const prompt = `You maintain the instructions (system prompt) of an AI operations agent at Bahn Express, a car delivery company.
The agent is the "${f.agent}" workflow. A person in the control room flagged a mistake it made.

THE PERSON'S COMPLAINT:
${f.complaint}

WHAT HAPPENED ON ORDER ${f.order_ref} (case timeline, oldest first):
${lines || '(no timeline lines)'}

THE AGENT'S CURRENT PROMPT (between the markers):
<<<PROMPT
${cur.prompt}
PROMPT>>>

Write the corrected prompt. Rules:
- Change as little as possible: add or reword the one or two rules that stop this mistake. Keep every other line exactly as it is.
- Keep the final "YOUR STAGES" line unchanged.
- A general rule, not a rule about this one order (no order numbers, names or prices from this case).
- Never remove a safety rule: a person approves bookings, costs, date changes and customer messages.

Reply with the full corrected prompt between <<<PROMPT and PROMPT>>>, then one line starting "WHY:" saying what you changed.`;
return [{ json: { prompt } }];

// Accept the draft only if it is a whole prompt (not a fragment) that still has the stages line; else fail loudly.
const cur = $('Current prompt').first().json, f = $('Check').first().json;
const text = String($json.text || '');
const m = text.match(/<<<PROMPT\s*([\s\S]*?)\s*PROMPT>>>/);
const why = (text.match(/WHY:\s*(.+)/) || [, 'no reason given'])[1].trim().slice(0, 400);
if (!m) throw new Error('the fixer did not return a prompt between the markers');
const prompt = m[1].trim();
if (!prompt.includes('YOUR STAGES')) throw new Error('the fixed prompt lost its YOUR STAGES line');
if (prompt.length < cur.prompt.length * 0.8) throw new Error('the fixed prompt is much shorter than the current one; refused');
if (prompt === cur.prompt.trim()) throw new Error('the fixer changed nothing');
return [{ json: { why, base_version: cur.version, body: { name: cur.name, type: 'text', prompt, labels: ['candidate'], config: cur.config || {},
  commitMessage: `Fix from ${f.operator} on ${f.order_ref}: ${f.complaint}`.slice(0, 500) } } }];

const f = $('Check').first().json, c = $('Candidate').first().json;
return [{ json: { order_ref: f.order_ref, agent: f.agent, complaint: f.complaint, base_version: String(c.base_version), version: String($json.version),
  why: c.why, status: 'testing', test_summary: '', decided_by: f.operator } }];
